import{_ as t,c as o,o as r,a2 as s}from"./chunks/framework.ZL09jyt0.js";const u=JSON.parse('{"title":"2026-01: Self-Hosted Shoot Exposure","description":"","frontmatter":{"github_repo":"https://github.com/gardener/documentation","github_subdir":"website/community/steering/technical","params":{"github_branch":"master"},"path_base_for_github_subdir":{"from":"content/community/steering/technical/2026-01-self-hosted-shoot-exposure.md","to":"2026-01-self-hosted-shoot-exposure.md"},"title":"2026-01: Self-Hosted Shoot Exposure","prev":false,"next":false},"headers":[],"relativePath":"community/steering/technical/2026-01-self-hosted-shoot-exposure/index.md","filePath":"community/steering/technical/2026-01-self-hosted-shoot-exposure.md","lastUpdated":null}'),a={name:"community/steering/technical/2026-01-self-hosted-shoot-exposure/index.md"};function i(n,e,l,d,c,h){return r(),o("div",null,e[0]||(e[0]=[s('<h1 id="_2026-01-self-hosted-shoot-exposure" tabindex="-1">2026-01: Self-Hosted Shoot Exposure <a class="header-anchor" href="#_2026-01-self-hosted-shoot-exposure" aria-label="Permalink to &quot;2026-01: Self-Hosted Shoot Exposure&quot;">​</a></h1><ul><li>✍🏻 <strong>Author(s):</strong> <a href="https://github.com/timebertt" target="_blank" rel="noreferrer">@timebertt</a> (Tim Ebert)</li><li>🗓️ <strong>Presentation:</strong> 2026-01-19, 16:00 - 17:00 CET</li><li>🎥 <strong>Recording:</strong> <a href="https://youtu.be/OodgUQ-cZNA" target="_blank" rel="noreferrer">click here</a></li><li>👨‍⚖️ <strong>Decisions:</strong><ul><li>Proceed with the proposed approach; the GEP will be merged and implemented as described.</li><li>Default domains are not relevant, as DNS is required already during bootstrapping; default domains only exist in the garden cluster (accessible only after <code>gardenadm connect</code>).</li><li>DNS strategy does not support health checks, but can support maintenance scenarios (e.g., cordoning nodes removes them from the endpoint set in the <code>SelfHostedShootExposure</code> API).</li><li>Disabling exposure should be possible and fall back to internal DNS (as it is used in the bootstrap phase).</li><li><code>provider-local</code> implementations with native support for <code>Service</code>s of type <code>LoadBalancer</code> (e.g., via <a href="https://github.com/kubernetes-sigs/cloud-provider-kind" target="_blank" rel="noreferrer"><code>cloud-provider-kind</code></a>, see <a href="https://gardener.cloud/community/hackathons/2025-11/#%E2%9A%96%EF%B8%8F%EF%B8%8F-load-balancer-controller-for-provider-local" target="_blank" rel="noreferrer">Hackathon results</a>) is independent, but we try to support it as part of this story.</li><li>What was previously considered a &quot;future optimization&quot; in the GEP is now part of the immediate optimization scope.</li><li>Direct <code>Node</code> querying (<a href="https://github.com/gardener/gardener/pull/13603#discussion_r2682478134" target="_blank" rel="noreferrer">PR discussion</a>) in the extension remains unchanged: prefer the existing approach over introducing a generic actuator, leveraging the existing <code>gardenlet</code> controller and <code>port</code> field in the <code>SelfHostedShootExposure</code> API.</li></ul></li></ul><h2 id="proposal" tabindex="-1">Proposal <a class="header-anchor" href="#proposal" aria-label="Permalink to &quot;Proposal&quot;">​</a></h2><p><a href="https://github.com/gardener/gardener/pull/13603" target="_blank" rel="noreferrer">GEP-36: Self-Hosted Shoot Exposure</a></p>',4)]))}const g=t(a,[["render",i]]);export{u as __pageData,g as default};
